// Gasto por cliente a partir de los pedidos pagados
PIPELINE ventas {
    SOURCE pedidos = CSV(file: "orders.csv");

    STEP pagados = FILTER {
        WHERE status IS NOT NULL AND amount > 2 * 5;
    }

    STEP por_cliente = AGGREGATE {
        GROUP_BY customer_id;
        SUM(amount) AS gastado;
        COUNT() AS compras;
    }

    STEP ranking = SORT {
        BY gastado DESC;
    }

    SINK reporte = PARQUET(file: "gasto_por_cliente.parquet");

    FLOW {
        pedidos -> pagados -> por_cliente -> ranking -> reporte;
    }
}

// Tutorial «De un CSV a un resultado»: cuánto gastó cada cliente.
// Datos: joins_pedidos.csv, incluido junto a este archivo.
PIPELINE gasto_por_cliente {
    // Contrato: columnas cliente e importe, en este orden y sin vacíos.
    SOURCE pedidos: TABLE[cliente: INT, importe: DECIMAL]
        = CSV(file: "joins_pedidos.csv");

    // Conserva solo los pedidos con importe positivo.
    STEP validos = FILTER {
        WHERE importe > 0;
    }

    // Añade el importe con IGV (18 %).
    STEP con_igv = DERIVE {
        importe_con_igv = importe * 1.18;
    }

    // Una fila por cliente: cantidad de pedidos y totales.
    STEP por_cliente = AGGREGATE {
        GROUP_BY cliente;
        COUNT() AS pedidos;
        SUM(importe) AS total;
        SUM(importe_con_igv) AS total_con_igv;
    }

    // Primero quien más gastó.
    STEP ranking = SORT {
        BY total DESC;
    }

    SINK reporte = CSV(file: "out/gasto_por_cliente.csv");

    FLOW {
        pedidos -> validos -> con_igv -> por_cliente -> ranking -> reporte;
    }
}

// Main ETL: SQLite -> cleansing / null handling -> aggregation -> Parquet
PIPELINE credit_risk {
    SOURCE clients = SQLITE(file: "bank.db", table: "clients");

    STEP cleaned = FILL_NULL {
        debt = 0;
    }

    STEP valid = FILTER {
        WHERE income IS NOT NULL AND income > 0 AND debt >= 0;
    }

    STEP enriched = DERIVE {
        debt_ratio = SAFE_DIVIDE(debt, income);
        segment_label = COALESCE(segment, "UNKNOWN");
    }

    STEP flagged = DERIVE {
        risk_flag = debt_ratio IS NULL;
    }

    STEP summary = AGGREGATE {
        GROUP_BY segment_label;
        COUNT() AS total_clients;
        COUNT(debt_ratio) AS ratios_available;
        AVG(debt_ratio) AS avg_debt_ratio;
    }

    SINK output = PARQUET(file: "summary.parquet");

    FLOW {
        clients -> cleaned -> valid -> enriched -> flagged -> summary -> output;
    }
}

// A reusable pipeline with an explicitly typed interface
PIPELINE clean_orders {
    INPUT orders: TABLE[id: INT, customer_id: INT, amount: DECIMAL?, status: STRING?];

    STEP non_null = DROP_NULLS {
        COLUMNS id, customer_id;
    }

    STEP normalized = FILL_NULL {
        status = "UNKNOWN";
        amount = 0;
    }

    OUTPUT cleaned: TABLE[id: INT, customer_id: INT, amount: DECIMAL, status: STRING];

    FLOW {
        orders -> non_null -> normalized -> cleaned;
    }
}

// Pipeline composition / two-input JOIN
PIPELINE order_report {
    SOURCE raw_orders = CSV(file: "orders.csv");
    SOURCE customers = SQLITE(file: "bank.db", table: "customers");
    USE clean_orders AS clean;

    STEP customer_keys = RENAME {
        id AS customer_key;
    }

    STEP joined = JOIN {
        TYPE LEFT;
        ON left.customer_id == right.customer_key;
    }
    STEP selected = SELECT {
        COLUMNS customer_id, amount, status;
    }
    SINK output = CSV(file: "orders_clean.csv");

    FLOW {
        raw_orders -> clean.orders;
        clean.cleaned -> joined.left;
        customers -> customer_keys -> joined.right;
        joined -> selected -> output;
    }
}

PIPELINE pendientes {
    SOURCE pedidos = CSV(file: "orders.csv");
    STEP sin_estado = FILTER { WHERE status == NULL; }
    SINK salida = CSV(file: "pendientes.csv");
    FLOW { pedidos -> sin_estado -> salida; }
}

// Compilar sin consultar ventas.csv:
// python main.py demo/rangos.etl --format ir --pases constantes,rangos
// Comparar con: python main.py demo/rangos.etl --format ir -O0
PIPELINE rangos {
    SOURCE ventas: TABLE[id: INT, monto: DECIMAL?] = CSV(file: "ventas.csv");
    STEP grandes = FILTER { WHERE monto >= 100; }
    STEP no_negativas = FILTER { WHERE monto >= 0; }
    STEP vista = SELECT { COLUMNS id, monto; }
    STEP validas = FILTER { WHERE monto IS NOT NULL AND monto < 1000; }
    OUTPUT resultado: TABLE[id: INT, monto: DECIMAL];
    FLOW { ventas -> grandes -> no_negativas -> vista -> validas -> resultado; }
}

